package com.polynomial.server;
import android.app.*;
import android.content.*;
import android.graphics.Color;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.webkit.*;
import android.widget.*;
import java.net.URI;
public class MainActivity extends Activity {
    private static final String DEFAULT="https://polynomial-server.tail722ac8.ts.net";
    private WebView web;
    private String server;
    private ValueCallback<Uri[]> chooser;
    private TextView status;
    private LinearLayout root;
    private int dp(int value) { return Math.round(value * getResources().getDisplayMetrics().density); }
    private boolean same(String url) { try { URI value=new URI(url),base=new URI(server);return "https".equalsIgnoreCase(value.getScheme())&&value.getHost()!=null&&value.getHost().equalsIgnoreCase(base.getHost())&&value.getPort()==base.getPort()&&value.getUserInfo()==null; } catch(Exception error) { return false; } }
    private String validServer(String value) throws Exception { URI uri=new URI(value.trim()); if(!"https".equalsIgnoreCase(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null||uri.getQuery()!=null||uri.getFragment()!=null||!(uri.getPath().isEmpty()||uri.getPath().equals("/")))throw new Exception("请输入完整的 HTTPS 服务器地址，不含路径和参数");return "https://"+uri.getAuthority(); }
    @Override public void onCreate(Bundle state) { super.onCreate(state);server=getPreferences(MODE_PRIVATE).getString("server",DEFAULT);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.WHITE);root.setOnApplyWindowInsetsListener((view,insets)->{view.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(10,0,10,0);bar.setBackgroundColor(Color.rgb(18,33,61));
        Button back=new Button(this);back.setText("‹");back.setOnClickListener(v->{if(web.canGoBack())web.goBack();});bar.addView(back,new LinearLayout.LayoutParams(dp(44),dp(48)));status=new TextView(this);status.setText("Polynomial");status.setTextColor(Color.WHITE);bar.addView(status,new LinearLayout.LayoutParams(0,dp(48),1));Button reload=new Button(this);reload.setText("↻");reload.setOnClickListener(v->web.reload());bar.addView(reload,new LinearLayout.LayoutParams(dp(44),dp(48)));Button config=new Button(this);config.setText("⚙");config.setContentDescription("连接设置");config.setOnClickListener(v->connection());bar.addView(config,new LinearLayout.LayoutParams(dp(44),dp(48)));root.addView(bar);
        web=new WebView(this);web.addJavascriptInterface(new Reminders(this), "PolynomialReminders");web.getSettings().setUserAgentString(web.getSettings().getUserAgentString()+" PolynomialClient/"+BuildConfig.VERSION_NAME+" (android; "+(Build.SUPPORTED_ABIS[0].contains("arm64")?"arm64":"universal")+")");web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);web.getSettings().setSafeBrowsingEnabled(true);web.getSettings().setSupportMultipleWindows(false);CookieManager.getInstance().setAcceptCookie(true);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);
        web.setWebViewClient(new WebViewClient(){ @Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){String url=request.getUrl().toString();if(same(url))return false; if(request.isForMainFrame())external(url);return true;} @Override public void onPageStarted(WebView view,String url,android.graphics.Bitmap icon){status.setText("正在连接…");} @Override public void onPageFinished(WebView view,String url){status.setText("Polynomial");CookieManager.getInstance().flush();} @Override public void onReceivedError(WebView view,WebResourceRequest request,WebResourceError error){if(request.isForMainFrame()){status.setText("连接失败");new AlertDialog.Builder(MainActivity.this).setTitle("暂时无法连接").setMessage("请检查网络和 Tailscale。登录数据保留在此设备。可以重试或修改连接地址。").setPositiveButton("重试",(d,w)->web.loadUrl(server+"/app.html")).setNeutralButton("连接设置",(d,w)->connection()).setNegativeButton("关闭",null).show();}} });
        web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView view,ValueCallback<Uri[]> callback,FileChooserParams params){if(chooser!=null)chooser.onReceiveValue(null);chooser=callback;try{startActivityForResult(params.createIntent(),101);return true;}catch(Exception error){chooser=null;callback.onReceiveValue(null);return false;}}@Override public boolean onJsAlert(WebView view,String url,String message,JsResult result){new AlertDialog.Builder(MainActivity.this).setMessage(message).setPositiveButton("确定",(d,w)->result.confirm()).setOnCancelListener(d->result.cancel()).show();return true;} });
        web.setDownloadListener((url,agent,disposition,mime,length)->{if(!same(url))return;try{DownloadManager.Request req=new DownloadManager.Request(Uri.parse(url));String cookie=CookieManager.getInstance().getCookie(url);if(cookie!=null)req.addRequestHeader("Cookie",cookie);req.setTitle(URLUtil.guessFileName(url,disposition,mime));req.setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED);req.setDestinationInExternalPublicDir(Environment.DIRECTORY_DOWNLOADS,URLUtil.guessFileName(url,disposition,mime));((DownloadManager)getSystemService(DOWNLOAD_SERVICE)).enqueue(req);Toast.makeText(this,"已开始下载",Toast.LENGTH_SHORT).show();}catch(Exception error){Toast.makeText(this,"下载失败，请在浏览器打开资源下载页",Toast.LENGTH_LONG).show();}});
        root.addView(web,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);if(state!=null)web.restoreState(state);else web.loadUrl(server+"/app.html"); }
    private void external(String url){try{Uri uri=Uri.parse(url);if("https".equals(uri.getScheme())||"mailto".equals(uri.getScheme()))startActivity(new Intent(Intent.ACTION_VIEW,uri));}catch(Exception ignored){}}
    private void connection(){EditText field=new EditText(this);field.setSingleLine(true);field.setText(server);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("连接设置").setMessage("请保持 Tailscale 连接。更换服务器会退出当前服务器会话。").setView(field).setPositiveButton("连接",null).setNegativeButton("取消",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{String target=validServer(field.getText().toString());if(!target.equals(server)){web.stopLoading();CookieManager.getInstance().removeAllCookies(null);web.clearHistory();}server=target;getPreferences(MODE_PRIVATE).edit().putString("server",server).apply();web.loadUrl(server+"/app.html");dialog.dismiss();}catch(Exception error){field.setError(error.getMessage());}}));dialog.show();}
    @Override protected void onActivityResult(int req,int result,Intent intent){super.onActivityResult(req,result,intent);if(req==101&&chooser!=null){chooser.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(result,intent));chooser=null;}}
    @Override public void onRequestPermissionsResult(int requestCode,String[] permissions,int[] results){super.onRequestPermissionsResult(requestCode,permissions,results);if(requestCode==202){Reminders.permissionResult(this);web.evaluateJavascript("window.dispatchEvent(new Event(\"polynomial-reminder-permission\"))",null);}}
    @Override public void onBackPressed(){if(web.canGoBack())web.goBack();else super.onBackPressed();}
    @Override public void onSaveInstanceState(Bundle state){web.saveState(state);super.onSaveInstanceState(state);}
    @Override protected void onDestroy(){if(chooser!=null)chooser.onReceiveValue(null);web.destroy();super.onDestroy();}
}
